const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const adirondacks = ee.Geometry.Point([-74.1, 44.1]).buffer(20000); // 20km buffer around a central point in Adirondacks

  const date1_start = '2022-10-01';
  const date1_end = '2022-10-02';
  const date2_start = '2022-10-08';
  const date2_end = '2022-10-09';

  // Sentinel-2 cloud masking function
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale to 0-1
  }

  // Function to calculate NDVI
  function addNDVI(image) {
    return image.addBands(image.normalizedDifference(['B8', 'B4']).rename('NDVI'));
  }

  // 2. Data Acquisition & Check
  const s2_collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filter(ee.Filter.intersects(adirondacks))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)); // Filter for less than 20% cloudiness

  const col1 = s2_collection.filterDate(date1_start, date1_end);
  const col2 = s2_collection.filterDate(date2_start, date2_end);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    console.log(`Images for Oct 1: ${size1}, Images for Oct 8: ${size2}`);
    console.log("C1"); // Empty Collection
    return;
  }

  // Apply cloud mask and add NDVI
  const img1_raw = col1.mosaic().clip(adirondacks);
  const img2_raw = col2.mosaic().clip(adirondacks);

  const img1 = addNDVI(maskS2clouds(img1_raw));
  const img2 = addNDVI(maskS2clouds(img2_raw));

  // 3. Processing (Calculate pixel count to detect C2)
  const scale = 1000; // Use a reasonable scale to avoid memory issues for region reduction

  const count1 = await img1.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: adirondacks,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const count2 = await img2.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: adirondacks,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (count1 === 0 || count2 === 0) {
    console.log(`Valid pixels for Oct 1: ${count1}, Valid pixels for Oct 8: ${count2}`);
    console.log("C2"); // No valid pixels
    return;
  }

  // 4. Calculation (Mean NDVI)
  // Lower NDVI indicates less green/more senescent (brown/orange) vegetation
  const mean_ndvi1 = await img1.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: adirondacks,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const mean_ndvi2 = await img2.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: adirondacks,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // 5. Validation & Final Answer
  if (mean_ndvi1 === null || mean_ndvi2 === null || isNaN(mean_ndvi1) || isNaN(mean_ndvi2)) {
    console.log(`NDVI Oct 1: ${mean_ndvi1}, NDVI Oct 8: ${mean_ndvi2}`);
    console.log("C3"); // Calculation Failure
    return;
  }

  console.log(`Images found for Oct 1: ${size1}, Oct 8: ${size2}`);
  console.log(`Valid pixels for Oct 1: ${count1}, Oct 8: ${count2}`);
  console.log(`Mean NDVI on Oct 1: ${mean_ndvi1.toFixed(3)}`);
  console.log(`Mean NDVI on Oct 8: ${mean_ndvi2.toFixed(3)}`);

  // Brown/orange areas are typically associated with lower NDVI values (less green vegetation).
  // So, if mean_ndvi2 (Oct 8) is lower than mean_ndvi1 (Oct 1), it suggests more brown/orange.
  if (mean_ndvi2 < mean_ndvi1) {
    console.log("A"); // Yes, more brown/orange areas (lower NDVI)
  } else {
    console.log("B"); // No, not more brown/orange areas
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
